{"query": "CREATE OR REPLACE TABLE qual AS
SELECT u.event_id, u.geoid FROM ubc u WHERE u.declared AND u.available AND u.source='utility_records'
AND u.peak_share_out >= 0.10 AND (u.hours_to_90pct_restored > 72 OR u.hours_to_90pct_reason='not_restored_in_window');
CREATE OR REPLACE TABLE hp AS
SELECT h.source_ID, h.NAME, h.COUNTYFIPS, h.TRAUMA, h.STATUS FROM hosp h WHERE h.STATUS='OPEN';
CREATE OR REPLACE TABLE pairs AS
SELECT DISTINCT hp.source_ID, hp.TRAUMA, q.event_id FROM hp JOIN qual q ON hp.COUNTYFIPS = q.geoid;
SELECT count(DISTINCT source_ID) hospitals, count(*) pairs, count(DISTINCT event_id) storms,
(SELECT count(*) FROM (SELECT source_ID FROM pairs GROUP BY source_ID HAVING count(DISTINCT event_id)>=2)) more_than_once
FROM pairs"}
